import argparse
import csv
import datetime
import io
import json
import re
import sys
from typing import List, Optional

from . import ledger


class _ReadError(Exception):
    pass


class _EntryError(Exception):
    pass


class _WriteError(Exception):
    pass


_DATE_ARG = re.compile(r"\d{4}-\d{2}-\d{2}", re.ASCII)


def _date_arg(text: str) -> datetime.date:
    if _DATE_ARG.fullmatch(text):
        try:
            return datetime.date(int(text[0:4]), int(text[5:7]), int(text[8:10]))
        except ValueError:
            pass
    raise argparse.ArgumentTypeError("invalid date %r (expected YYYY-MM-DD)" % text)


def _build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="pennywise")
    sub = parser.add_subparsers(dest="command", required=True, metavar="COMMAND")

    p_balance = sub.add_parser("balance", help="print the total of all entries")
    p_balance.add_argument("file", metavar="FILE", help="ledger file, or - for stdin")
    p_balance.add_argument("--json", action="store_true", help="print JSON")
    p_balance.set_defaults(handler=_cmd_balance)

    p_summary = sub.add_parser("summary", help="print totals per category or month")
    p_summary.add_argument("file", metavar="FILE", help="ledger file, or - for stdin")
    p_summary.add_argument(
        "--by", choices=("category", "month"), default="category",
        help="group by category (default) or month",
    )
    p_summary.add_argument("--json", action="store_true", help="print JSON")
    p_summary.set_defaults(handler=_cmd_summary)

    p_list = sub.add_parser("list", help="print entries, oldest first")
    p_list.add_argument("file", metavar="FILE", help="ledger file, or - for stdin")
    p_list.add_argument("--category", metavar="C", help="only this category (any case)")
    p_list.add_argument("--since", metavar="YYYY-MM-DD", type=_date_arg,
                        help="only entries on or after this date")
    p_list.add_argument("--until", metavar="YYYY-MM-DD", type=_date_arg,
                        help="only entries on or before this date")
    p_list.add_argument("--json", action="store_true", help="print JSON")
    p_list.set_defaults(handler=_cmd_list)

    p_add = sub.add_parser("add", help="append one validated entry to a ledger file")
    p_add.add_argument("file", metavar="FILE", help="ledger file (created if missing)")
    p_add.add_argument("date", metavar="DATE", help="YYYY-MM-DD")
    p_add.add_argument("category", metavar="CATEGORY", help="one word")
    p_add.add_argument("amount", metavar="AMOUNT", help="e.g. 12.5 or -42")
    p_add.add_argument("note", metavar="NOTE", nargs="?", default="",
                       help="optional note, one quoted argument")
    p_add.set_defaults(handler=_cmd_add)

    p_export = sub.add_parser("export", help="print entries as CSV, oldest first")
    p_export.add_argument("file", metavar="FILE", help="ledger file, or - for stdin")
    p_export.add_argument("--format", choices=("csv",), default="csv",
                          help="output format (only csv)")
    p_export.set_defaults(handler=_cmd_export)
    return parser


def _read_ledger(path: str) -> str:
    try:
        if path == "-":
            stream = sys.stdin
            raw = getattr(stream, "buffer", None)
            if raw is None:
                return stream.read()
            return raw.read().decode("utf-8")
        with open(path, "rb") as handle:
            return handle.read().decode("utf-8")
