        raise _ReadError("cannot read %s: %s" % (path, exc)) from None


def _cmd_balance(args: argparse.Namespace) -> str:
    entries = ledger.parse(_read_ledger(args.file))
    total = ledger.format_amount(ledger.balance(entries))
    if args.json:
        return json.dumps({"balance": total})
    return total


def _cmd_summary(args: argparse.Namespace) -> Optional[str]:
    entries = ledger.parse(_read_ledger(args.file))
    group = ledger.by_month if args.by == "month" else ledger.by_category
    totals = {k: ledger.format_amount(v) for k, v in sorted(group(entries).items())}
    if args.json:
        return json.dumps(totals, sort_keys=True)
    if not totals:
        return None
    return "\n".join("%s  %s" % item for item in totals.items())


def _cmd_list(args: argparse.Namespace) -> Optional[str]:
    entries = ledger.parse(_read_ledger(args.file))
    entries = ledger.filter_entries(entries, args.category, args.since, args.until)
    entries = ledger.sort_entries(entries)
    if args.json:
        return json.dumps([
            {
                "date": e.date.isoformat(),
                "category": e.category,
                "amount": ledger.format_amount(e.amount),
                "note": e.note,
            }
            for e in entries
        ])
    if not entries:
        return None
    return "\n".join(ledger.format_entry(e) for e in entries)


def _cmd_export(args: argparse.Namespace) -> str:
    entries = ledger.sort_entries(ledger.parse(_read_ledger(args.file)))
    buf = io.StringIO()
    writer = csv.writer(buf, lineterminator="\n")
    writer.writerow(["date", "category", "amount", "note"])
    for e in entries:
        writer.writerow([e.date.isoformat(), e.category,
                         ledger.format_amount(e.amount), e.note])
    return buf.getvalue()[:-1]  # main() prints the final newline


def _has_line_break(text: str) -> bool:
    return len(("x" + text + "x").splitlines()) > 1


def _build_entry(args: argparse.Namespace) -> ledger.Entry:
    for value in (args.date, args.category, args.amount):
        if not value or re.search(r"[ \t]", value):
            raise _EntryError(
                "invalid entry: DATE, CATEGORY and AMOUNT must be non-empty "
                "and contain no spaces or tabs"
            )
    if any(_has_line_break(ch) for ch in args.note):
        raise _EntryError("invalid entry: note must not contain a line break")
    text = "%s %s %s %s" % (args.date, args.category, args.amount, args.note)
    try:
        entries = ledger.parse(text)
    except ledger.ParseError as exc:
        raise _EntryError("invalid entry: %s" % exc.message) from None
    if len(entries) != 1:
        raise _EntryError("invalid entry: expected DATE CATEGORY AMOUNT [NOTE]")
    return entries[0]


def _cmd_add(args: argparse.Namespace) -> str:
    line = ledger.format_entry(_build_entry(args))
    try:
        payload = (line + "\n").encode("utf-8")
    except UnicodeEncodeError:
        raise _EntryError("invalid entry: note is not valid text") from None
    try:
        with open(args.file, "ab+") as handle:
            size = handle.seek(0, 2)
            if size > 0:
                handle.seek(size - 1)
                if handle.read(1) != b"\n":
                    payload = b"\n" + payload
            handle.seek(0, 2)
            handle.write(payload)
    except OSError as exc:
        raise _WriteError("cannot write %s: %s" % (args.file, exc)) from None
    return line


def main(argv: Optional[List[str]] = None) -> int:
    parser = _build_parser()
    try:
        args = parser.parse_args(argv)
    except SystemExit as exc:
        code = exc.code
        return code if isinstance(code, int) else (0 if code is None else 2)
    try:
        output = args.handler(args)
    except ledger.ParseError as exc:
        print("pennywise: %s" % exc, file=sys.stderr)
        return 1
    except _EntryError as exc:
        print("pennywise: %s" % exc, file=sys.stderr)
        return 1
    except (_ReadError, _WriteError) as exc:
        print("pennywise: %s" % exc, file=sys.stderr)
        return 2
    if output is not None:
        print(output)
    return 0
"""Ledger model, parser and totals."""

import datetime
import re
from dataclasses import dataclass
from decimal import ROUND_HALF_EVEN, Decimal, localcontext
from typing import Callable, Dict, Iterable, List, Optional

__all__ = [
    "Entry",
    "ParseError",
    "parse",
    "balance",
    "by_category",
    "by_month",
    "filter_entries",
    "format_amount",
    "format_entry",
    "sort_entries",
]

_DATE_RE = re.compile(r"\d{4}-\d{2}-\d{2}", re.ASCII)
_AMOUNT_RE = re.compile(r"[+-]?\d+(\.\d{1,2})?", re.ASCII)
_FIELD_SEP = re.compile(r"[ \t]+")


@dataclass(frozen=True)
class Entry:
    date: datetime.date
    category: str
    amount: Decimal
    note: str = ""


class ParseError(ValueError):
    """A ledger line is invalid. ``line`` is the 1-based physical line number."""

    def __init__(self, line: int, message: str) -> None:
        super().__init__(line, message)
        self.line = line
        self.message = message

    def __str__(self) -> str:
        return "line %d: %s" % (self.line, self.message)


def _parse_line(number: int, line: str) -> Entry:
    fields = _FIELD_SEP.split(line.strip(" \t"), 3)
    if len(fields) < 3:
        raise ParseError(number, "expected DATE CATEGORY AMOUNT [NOTE]")
    date_text, category, amount_text = fields[0], fields[1], fields[2]
    note = fields[3].strip() if len(fields) > 3 else ""

    if not _DATE_RE.fullmatch(date_text):
        raise ParseError(number, "invalid date %r" % date_text)
    try:
        date = datetime.date(
            int(date_text[0:4]), int(date_text[5:7]), int(date_text[8:10])
        )
    except ValueError:
        raise ParseError(number, "invalid date %r" % date_text) from None

    if not _AMOUNT_RE.fullmatch(amount_text):
        raise ParseError(number, "invalid amount %r" % amount_text)

    return Entry(date, category.lower(), Decimal(amount_text), note)


def parse(text: str) -> List[Entry]:
    """Parse ledger text into entries, in file order."""
    entries = []
    for number, line in enumerate(text.splitlines(), start=1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        entries.append(_parse_line(number, line))
    return entries


def balance(entries: Iterable[Entry]) -> Decimal:
    """Total of all amounts (``Decimal(0)`` for no entries)."""
    return sum((e.amount for e in entries), Decimal(0))


def _group(entries: Iterable[Entry], key: Callable[[Entry], str]) -> Dict[str, Decimal]:
    totals: Dict[str, Decimal] = {}
    for entry in entries:
        k = key(entry)
        totals[k] = totals.get(k, Decimal(0)) + entry.amount
    return totals


def by_category(entries: Iterable[Entry]) -> Dict[str, Decimal]:
    """Total per lower-case category, keys in order of first appearance."""
    return _group(entries, lambda e: e.category)


def by_month(entries: Iterable[Entry]) -> Dict[str, Decimal]:
    """Total per ``YYYY-MM``, keys in order of first appearance."""
    return _group(entries, lambda e: "%04d-%02d" % (e.date.year, e.date.month))


def format_amount(amount: Decimal) -> str:
    """Two decimals, plain digits, ``-`` only for negatives, never ``-0.00``."""
    with localcontext() as ctx:
        ctx.prec = max(ctx.prec, len(amount.as_tuple().digits) + 4)
        quantized = amount.quantize(Decimal("0.01"), rounding=ROUND_HALF_EVEN)
    if quantized == 0:
        quantized = abs(quantized)
    return format(quantized, "f")


def filter_entries(
    entries: Iterable[Entry],
    category: Optional[str] = None,
    since: Optional[datetime.date] = None,
    until: Optional[datetime.date] = None,
) -> List[Entry]:
    """Matching entries as a new list, in the order given.

    ``category`` is compared case-insensitively; ``since`` and ``until`` are
    inclusive. ``None`` means not filtered on.
    """
    wanted = category.lower() if category is not None else None
    return [
        e
        for e in entries
        if (wanted is None or e.category == wanted)
        and (since is None or e.date >= since)
        and (until is None or e.date <= until)
    ]


def sort_entries(entries: Iterable[Entry]) -> List[Entry]:
    """New list, oldest first; same-day entries keep their given order."""
    return sorted(entries, key=lambda e: e.date)


def format_entry(entry: Entry) -> str:
    """Canonical one-line form: ``DATE CATEGORY AMOUNT NOTE`` (no trailing space)."""
    line = "%s %s %s" % (entry.date.isoformat(), entry.category, format_amount(entry.amount))
    return "%s %s" % (line, entry.note) if entry.note else line

