"""Command-line interface."""

import argparse
import csv
import datetime
import io
import json
import re
import sys
from typing import List, Optional

from . import ledger


class _ReadError(Exception):
    pass


class _EntryError(Exception):
    pass


class _WriteError(Exception):
    pass


_DATE_ARG = re.compile(r"\d{4}-\d{2}-\d{2}", re.ASCII)


def _date_arg(text: str) -> datetime.date:
    if _DATE_ARG.fullmatch(text):
        try:
            return datetime.date(int(text[0:4]), int(text[5:7]), int(text[8:10]))
        except ValueError:
            pass
    raise argparse.ArgumentTypeError("invalid date %r (expected YYYY-MM-DD)" % text)


def _build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="pennywise")
    sub = parser.add_subparsers(dest="command", required=True, metavar="COMMAND")

    p_balance = sub.add_parser("balance", help="print the total of all entries")
    p_balance.add_argument("file", metavar="FILE", help="ledger file, or - for stdin")
    p_balance.add_argument("--json", action="store_true", help="print JSON")
    p_balance.set_defaults(handler=_cmd_balance)

    p_summary = sub.add_parser("summary", help="print totals per category or month")
    p_summary.add_argument("file", metavar="FILE", help="ledger file, or - for stdin")
    p_summary.add_argument(
        "--by", choices=("category", "month"), default="category",
        help="group by category (default) or month",
    )
    p_summary.add_argument("--json", action="store_true", help="print JSON")
    p_summary.set_defaults(handler=_cmd_summary)

    p_list = sub.add_parser("list", help="print entries, oldest first")
    p_list.add_argument("file", metavar="FILE", help="ledger file, or - for stdin")
    p_list.add_argument("--category", metavar="C", help="only this category (any case)")
    p_list.add_argument("--since", metavar="YYYY-MM-DD", type=_date_arg,
                        help="only entries on or after this date")
    p_list.add_argument("--until", metavar="YYYY-MM-DD", type=_date_arg,
                        help="only entries on or before this date")
    p_list.add_argument("--json", action="store_true", help="print JSON")
    p_list.set_defaults(handler=_cmd_list)

    p_add = sub.add_parser("add", help="append one validated entry to a ledger file")
    p_add.add_argument("file", metavar="FILE", help="ledger file (created if missing)")
    p_add.add_argument("date", metavar="DATE", help="YYYY-MM-DD")
    p_add.add_argument("category", metavar="CATEGORY", help="one word")
    p_add.add_argument("amount", metavar="AMOUNT", help="e.g. 12.5 or -42")
    p_add.add_argument("note", metavar="NOTE", nargs="?", default="",
                       help="optional note, one quoted argument")
    p_add.set_defaults(handler=_cmd_add)

    p_export = sub.add_parser("export", help="print entries as CSV, oldest first")
    p_export.add_argument("file", metavar="FILE", help="ledger file, or - for stdin")
    p_export.add_argument("--format", choices=("csv",), default="csv",
                          help="output format (only csv)")
    p_export.set_defaults(handler=_cmd_export)
    return parser


def _read_ledger(path: str) -> str:
    try:
        if path == "-":
            stream = sys.stdin
            raw = getattr(stream, "buffer", None)
            if raw is None:
                return stream.read()
            return raw.read().decode("utf-8")
        with open(path, "rb") as handle:
            return handle.read().decode("utf-8")
    except (OSError, UnicodeDecodeError) as exc:
        raise _ReadError("cannot read %s: %s" % (path, exc)) from None


def _cmd_balance(args: argparse.Namespace) -> str:
    entries = ledger.parse(_read_ledger(args.file))
    total = ledger.format_amount(ledger.balance(entries))
    if args.json:
        return json.dumps({"balance": total})
    return total


def _cmd_summary(args: argparse.Namespace) -> Optional[str]:
    entries = ledger.parse(_read_ledger(args.file))
    group = ledger.by_month if args.by == "month" else ledger.by_category
    totals = {k: ledger.format_amount(v) for k, v in sorted(group(entries).items())}
    if args.json:
        return json.dumps(totals, sort_keys=True)
    if not totals:
        return None
    return "\n".join("%s  %s" % item for item in totals.items())


def _cmd_list(args: argparse.Namespace) -> Optional[str]:
    entries = ledger.parse(_read_ledger(args.file))
    entries = ledger.filter_entries(entries, args.category, args.since, args.until)
    entries = ledger.sort_entries(entries)
    if args.json:
        return json.dumps([
            {
                "date": e.date.isoformat(),
                "category": e.category,
                "amount": ledger.format_amount(e.amount),
                "note": e.note,
            }
            for e in entries
        ])
    if not entries:
        return None
    return "\n".join(ledger.format_entry(e) for e in entries)


def _cmd_export(args: argparse.Namespace) -> str:
    entries = ledger.sort_entries(ledger.parse(_read_ledger(args.file)))
    buf = io.StringIO()
    writer = csv.writer(buf, lineterminator="\n")
    writer.writerow(["date", "category", "amount", "note"])
    for e in entries:
        writer.writerow([e.date.isoformat(), e.category,
                         ledger.format_amount(e.amount), e.note])
    return buf.getvalue()[:-1]  # main() prints the final newline


def _has_line_break(text: str) -> bool:
    return len(("x" + text + "x").splitlines()) > 1


def _build_entry(args: argparse.Namespace) -> ledger.Entry:
    for value in (args.date, args.category, args.amount):
        if not value or re.search(r"[ \t]", value):
            raise _EntryError(
                "invalid entry: DATE, CATEGORY and AMOUNT must be non-empty "
                "and contain no spaces or tabs"
            )
    if any(_has_line_break(ch) for ch in args.note):
        raise _EntryError("invalid entry: note must not contain a line break")
    text = "%s %s %s %s" % (args.date, args.category, args.amount, args.note)
    try:
        entries = ledger.parse(text)
    except ledger.ParseError as exc:
        raise _EntryError("invalid entry: %s" % exc.message) from None
    if len(entries) != 1:
        raise _EntryError("invalid entry: expected DATE CATEGORY AMOUNT [NOTE]")
    return entries[0]


def _cmd_add(args: argparse.Namespace) -> str:
    line = ledger.format_entry(_build_entry(args))
    try:
        payload = (line + "\n").encode("utf-8")
    except UnicodeEncodeError:
        raise _EntryError("invalid entry: note is not valid text") from None
    try:
        with open(args.file, "ab+") as handle:
            size = handle.seek(0, 2)
            if size > 0:
                handle.seek(size - 1)
                if handle.read(1) != b"\n":
                    payload = b"\n" + payload
            handle.seek(0, 2)
            handle.write(payload)
    except OSError as exc:
        raise _WriteError("cannot write %s: %s" % (args.file, exc)) from None
    return line


def main(argv: Optional[List[str]] = None) -> int:
    parser = _build_parser()
    try:
        args = parser.parse_args(argv)
    except SystemExit as exc:
        code = exc.code
        return code if isinstance(code, int) else (0 if code is None else 2)
    try:
        output = args.handler(args)
    except ledger.ParseError as exc:
        print("pennywise: %s" % exc, file=sys.stderr)
        return 1
    except _EntryError as exc:
        print("pennywise: %s" % exc, file=sys.stderr)
        return 1
    except (_ReadError, _WriteError) as exc:
        print("pennywise: %s" % exc, file=sys.stderr)
        return 2
    if output is not None:
        print(output)
    return 0
